  parameterHelp.pwm_compensation_m2 = "M2 左履带的起步 PWM 补偿。只在非零电机输出上叠加；数值过大可能造成起步突跳。修改时会与 M1 成对写入 STM32 Flash。";
  parameterReferences.pwm_compensation_m1 = "2736";
